<#
  12월 달력 표시 + 갤러리 순차 등장

  1) D-DAY 섹션에 예식이 있는 달의 달력을 넣고 예식일(19일)을 강조합니다.
     날짜만 보여주므로 외부 알림용에도 그대로 나옵니다.

  2) 갤러리 격자가 화면에 들어오는 순간부터 칸이 순서대로 나타납니다.
     원래도 애니메이션은 있었지만 페이지가 열릴 때 한꺼번에 재생돼서,
     스크롤해서 갤러리에 도착하면 이미 끝나 있었습니다.
     이제 각 장소 격자가 화면에 들어올 때 60ms 간격으로 하나씩 뜹니다.

  바뀌는 파일 5개:
    src\hooks\useInView.js                        (새 파일) 화면 진입 감지
    src\components\common\WeddingCalendar.jsx     (새 파일) 달력
    src\components\common\DdaySection.jsx         달력 삽입
    src\components\common\GallerySection.jsx      격자 순차 등장
    src\styles\globals.css                        칸 애니메이션 조건 변경

  ⚠️ invitationConfig.js 는 건드리지 않습니다.
  ⚠️ apply-sections.ps1 을 먼저 실행한 상태여야 합니다.

  두는 곳: C:\Users\sb622\OneDrive\문서\GitHub\mobile-invitation\apply-calendar-gallery.ps1
  실행:
      cd "C:\Users\sb622\OneDrive\문서\GitHub\mobile-invitation"
      powershell -ExecutionPolicy Bypass -File .\apply-calendar-gallery.ps1

  되돌리려면:
      git checkout -- src/components src/styles
      Remove-Item src\hooks\useInView.js, src\components\common\WeddingCalendar.jsx
#>

$ErrorActionPreference = 'Stop'

if (-not (Test-Path .\package.json)) {
  Write-Host '프로젝트 폴더에서 실행하세요 (package.json 이 있는 곳).' -ForegroundColor Red
  Write-Host ('현재 위치: ' + (Get-Location)) -ForegroundColor Yellow
  exit 1
}

if (-not (Test-Path .\src\lib\visibility.js)) {
  Write-Host 'apply-sections.ps1 을 먼저 실행하세요. (src\lib\visibility.js 가 없습니다)' -ForegroundColor Red
  exit 1
}

function Write-ProjectFile {
  param([string]$Path, [string]$Base64)
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
  }
  [IO.File]::WriteAllBytes(
    (Join-Path (Get-Location) $Path),
    [Convert]::FromBase64String($Base64)
  )
  Write-Host ('  덮어씀  ' + $Path)
}

