Write-Host ''
$checks = @(
  @{ Name = '화면 진입 감지';   Path = 'src\hooks\useInView.js';                     Pattern = 'IntersectionObserver' },
  @{ Name = '달력 컴포넌트';    Path = 'src\components\common\WeddingCalendar.jsx';  Pattern = 'WEEKDAY_LABELS' },
  @{ Name = 'D-DAY 에 달력';    Path = 'src\components\common\DdaySection.jsx';      Pattern = 'WeddingCalendar' },
  @{ Name = '갤러리 순차 등장'; Path = 'src\components\common\GallerySection.jsx';   Pattern = 'cells-in' },
  @{ Name = 'CSS 조건 변경';    Path = 'src\styles\globals.css';                     Pattern = '\.cells-in \.gallery-cell' }
)

$fail = 0
foreach ($c in $checks) {
  if (Select-String -Path $c.Path -Pattern $c.Pattern -Quiet) {
    Write-Host ('  [OK] ' + $c.Name) -ForegroundColor Green
  } else {
    Write-Host ('  [실패] ' + $c.Name) -ForegroundColor Red
    $fail++
  }
}

Write-Host ''
if ($fail -eq 0) { Write-Host '모두 적용됐습니다.' -ForegroundColor Green }
else             { Write-Host "$fail 건 실패. 위 목록을 알려주세요." -ForegroundColor Red }

Write-Host ''
Write-Host '개발 서버를 껐다가 다시 켜세요 (Ctrl+C 후 npm run dev).' -ForegroundColor Cyan
Write-Host '갤러리 효과는 페이지 맨 위에서 천천히 스크롤해 내려가며 확인하세요.' -ForegroundColor Cyan
